import type { NextConfig } from "next";

// Decision: no cacheComponents or partialPrefetching, which create-next-app
// switched on. Both are about rendering pages on the server ahead of time,
// and this app renders in the browser: who is logged in is only known once
// the token is read from localStorage. With them on, Next warns on every
// logged-in page that it could not pre-render it.
const nextConfig: NextConfig = {
  // Tailwind v4's loader for Turbopack, as generated by create-next-app.
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
